```javascript
// Solicita datos JSON a un endpoint público
fetch('https://api.example.com/users')
  .then(res => {
    if (!res.ok) throw new Error(`Error ${res.status}`);
    return res.json();
  })
  .then(data => console.log(data))
  .catch(err => console.error(err));
```
